```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock the context providers
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockItems = [
  { id: '1', name: 'Epic Scroll', price: 29.99 },
  { id: '2', name: 'Golden Lyre', price: 149.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 179.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component - An Epic in Tests', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-OLYMPUS-123' });
  });

  // === HAPPY PATH: THE HERO'S JOURNEY ===
  describe('Complete Checkout Flow', () => {
    it('guides the user from shipping through confirmation', async () => {
      // Arrange
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Act - Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Mount Olympus');
      await user.type(screen.getByLabelText(/city/i), 'Athens');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Zeus Thunderbolt');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review step
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('Order Confirmed');
        expect(screen.getByText('ORD-OLYMPUS-123')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-OLYMPUS-123');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  // === VALIDATION: GUARDING THE GATES ===
  describe('Shipping Form Validation', () => {
    it('displays error when street address is empty', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(await screen.findByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(await screen.findByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Payment Form Validation', () => {
    it('requires valid 16-digit card number', async () => {
      render(<Checkout />);
      // Navigate to payment
      await fillShippingForm(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(await screen.findByText(/valid 16-digit card/i)).toBeInTheDocument();
    });
  });

  // === ERROR STATES: TRIALS OF THE HERO ===
  describe('Payment Error Handling', () => {
    it('displays error and allows retry when payment fails', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined by the Fates'));
      render(<Checkout />);

      await completeToReviewStep(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent('Card declined by the Fates');
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // === LOADING STATES: PATIENCE OF ODYSSEUS ===
  describe('Loading States', () => {
    it('disables buttons and shows loading text during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      render(<Checkout />);

      await completeToReviewStep(user);
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  // === EDGE CASES: MONSTERS OF THE DEEP ===
  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValueOnce({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // === ACCESSIBILITY: GIFTS TO ALL MORTALS ===
  describe('Accessibility', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('announces errors to screen readers', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const alerts = await screen.findAllByRole('alert');
      expect(alerts.length).toBeGreaterThan(0);
    });
  });
});

// Helper functions - worthy companions on this journey
async function fillShippingForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/street/i), '123 Test St');
  await user.type(screen.getByLabelText(/city/i), 'TestCity');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip/i), '12345');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReviewStep(user: ReturnType<typeof userEvent.setup>) {
  await fillShippingForm(user);
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Test User');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
